insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-playstation-history-trivia',
  'PlayStation Trivia: How Well Do You Know Its History?',
  'Eight questions on PlayStation history: launch years, record-breaking consoles and the studios behind its biggest exclusives.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'gaming'),
  '[{"id":"q1","question":"In which year was the original PlayStation released in Japan?","options":[{"id":"a","text":"1992","is_correct":false},{"id":"b","text":"1994","is_correct":true},{"id":"c","text":"1996","is_correct":false},{"id":"d","text":"1998","is_correct":false}],"explanation":"The first PlayStation launched in Japan on 3 December 1994 and reached the West in 1995."},{"id":"q2","question":"Sony originally planned a CD-ROM add-on for which company''s console before building its own?","options":[{"id":"a","text":"Sega","is_correct":false},{"id":"b","text":"Nintendo","is_correct":true},{"id":"c","text":"Atari","is_correct":false},{"id":"d","text":"NEC","is_correct":false}],"explanation":"The ''Play Station'' SNES add-on deal with Nintendo collapsed in 1991, pushing Sony to make its own console."},{"id":"q3","question":"Which engineer is known as the ''father of the PlayStation''?","options":[{"id":"a","text":"Ken Kutaragi","is_correct":true},{"id":"b","text":"Shigeru Miyamoto","is_correct":false},{"id":"c","text":"Nolan Bushnell","is_correct":false},{"id":"d","text":"Yu Suzuki","is_correct":false}],"explanation":"Kutaragi championed the project inside Sony and led the first three PlayStation consoles."},{"id":"q4","question":"What is the best-selling home console of all time?","options":[{"id":"a","text":"Nintendo DS","is_correct":false},{"id":"b","text":"Wii","is_correct":false},{"id":"c","text":"PlayStation 2","is_correct":true},{"id":"d","text":"PlayStation 4","is_correct":false}],"explanation":"The PS2, launched in 2000, sold over 155 million units, more than any other home console."},{"id":"q5","question":"Which PlayStation console was the first to play Blu-ray discs?","options":[{"id":"a","text":"PlayStation 2","is_correct":false},{"id":"b","text":"PlayStation 3","is_correct":true},{"id":"c","text":"PlayStation 4","is_correct":false},{"id":"d","text":"PlayStation 5","is_correct":false}],"explanation":"The PS3, released in 2006, included a Blu-ray drive that also helped the format win over HD DVD."},{"id":"q6","question":"Which character did Naughty Dog introduce on the PlayStation in 1996?","options":[{"id":"a","text":"Spyro the Dragon","is_correct":false},{"id":"b","text":"Lara Croft","is_correct":false},{"id":"c","text":"Solid Snake","is_correct":false},{"id":"d","text":"Crash Bandicoot","is_correct":true}],"explanation":"Crash Bandicoot debuted in 1996 and became an unofficial PlayStation mascot."},{"id":"q7","question":"Which studio developed the 2018 God of War reboot?","options":[{"id":"a","text":"Naughty Dog","is_correct":false},{"id":"b","text":"Guerrilla Games","is_correct":false},{"id":"c","text":"Santa Monica Studio","is_correct":true},{"id":"d","text":"Insomniac Games","is_correct":false}],"explanation":"Santa Monica Studio, with director Cory Barlog, moved the saga to Norse mythology."},{"id":"q8","question":"In which year did the PlayStation 5 launch?","options":[{"id":"a","text":"2018","is_correct":false},{"id":"b","text":"2019","is_correct":false},{"id":"c","text":"2020","is_correct":true},{"id":"d","text":"2021","is_correct":false}],"explanation":"The PS5 launched in November 2020."}]'::jsonb,
  null,
  array['gaming', 'playstation', 'trivia', 'consoles', 'sony']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

