insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-xbox-history-trivia',
  'Xbox Trivia: How Well Do You Know Microsoft''s Consoles?',
  'Eight questions on Xbox history: the 2001 debut, Halo, Xbox 360, the Red Ring of Death and Game Pass.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'gaming'),
  '[{"id":"q1","question":"In which year did Microsoft release the original Xbox?","options":[{"id":"a","text":"1999","is_correct":false},{"id":"b","text":"2001","is_correct":true},{"id":"c","text":"2003","is_correct":false},{"id":"d","text":"2005","is_correct":false}],"explanation":"The first Xbox debuted in November 2001, Microsoft''s entry into the console market."},{"id":"q2","question":"Which launch title became the flagship game of the first Xbox?","options":[{"id":"a","text":"Halo: Combat Evolved","is_correct":true},{"id":"b","text":"Gears of War","is_correct":false},{"id":"c","text":"Forza Motorsport","is_correct":false},{"id":"d","text":"Fable","is_correct":false}],"explanation":"Halo: Combat Evolved launched alongside the console in 2001 and defined the brand."},{"id":"q3","question":"Which Microsoft online gaming service launched in 2002?","options":[{"id":"a","text":"Xbox Live","is_correct":true},{"id":"b","text":"Xbox Game Pass","is_correct":false},{"id":"c","text":"Games for Windows – Live","is_correct":false},{"id":"d","text":"MSN Games","is_correct":false}],"explanation":"Xbox Live brought broadband online play to consoles in November 2002."},{"id":"q4","question":"In which year did the Xbox 360 launch?","options":[{"id":"a","text":"2003","is_correct":false},{"id":"b","text":"2005","is_correct":true},{"id":"c","text":"2007","is_correct":false},{"id":"d","text":"2009","is_correct":false}],"explanation":"The Xbox 360 launched in November 2005, a year ahead of the PS3."},{"id":"q5","question":"What was the nickname of the Xbox 360''s infamous hardware failure?","options":[{"id":"a","text":"Blue Screen of Death","is_correct":false},{"id":"b","text":"Yellow Light of Death","is_correct":false},{"id":"c","text":"Red Ring of Death","is_correct":true},{"id":"d","text":"Green Flash of Death","is_correct":false}],"explanation":"Three red quadrants around the power button signalled a general hardware failure."},{"id":"q6","question":"Which studio created the Halo series?","options":[{"id":"a","text":"343 Industries","is_correct":false},{"id":"b","text":"Bungie","is_correct":true},{"id":"c","text":"Epic Games","is_correct":false},{"id":"d","text":"Infinity Ward","is_correct":false}],"explanation":"Bungie developed Halo through Reach (2010); 343 Industries took over the series afterwards."},{"id":"q7","question":"In which year did Microsoft launch Xbox Game Pass?","options":[{"id":"a","text":"2013","is_correct":false},{"id":"b","text":"2015","is_correct":false},{"id":"c","text":"2017","is_correct":true},{"id":"d","text":"2019","is_correct":false}],"explanation":"Game Pass launched in June 2017 with a rotating subscription catalogue."},{"id":"q8","question":"Which publisher behind The Elder Scrolls and Fallout did Microsoft acquire in 2021?","options":[{"id":"a","text":"Activision Blizzard","is_correct":false},{"id":"b","text":"Ubisoft","is_correct":false},{"id":"c","text":"Electronic Arts","is_correct":false},{"id":"d","text":"Bethesda","is_correct":true}],"explanation":"Microsoft bought ZeniMax Media, Bethesda''s parent company, in March 2021."}]'::jsonb,
  null,
  array['gaming', 'xbox', 'trivia', 'consoles', 'halo']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

