e hardware."},{"id":"q6","question":"¿Qué estudio creó la saga Halo?","options":[{"id":"a","text":"343 Industries","is_correct":false},{"id":"b","text":"Bungie","is_correct":true},{"id":"c","text":"Epic Games","is_correct":false},{"id":"d","text":"Infinity Ward","is_correct":false}],"explanation":"Bungie desarrolló la saga hasta Reach (2010); después tomó el relevo 343 Industries."},{"id":"q7","question":"¿En qué año lanzó Microsoft Xbox Game Pass?","options":[{"id":"a","text":"2013","is_correct":false},{"id":"b","text":"2015","is_correct":false},{"id":"c","text":"2017","is_correct":true},{"id":"d","text":"2019","is_correct":false}],"explanation":"Game Pass empezó en junio de 2017 con un catálogo rotativo por suscripción."},{"id":"q8","question":"¿Qué editora detrás de The Elder Scrolls y Fallout compró Microsoft en 2021?","options":[{"id":"a","text":"Activision Blizzard","is_correct":false},{"id":"b","text":"Ubisoft","is_correct":false},{"id":"c","text":"Electronic Arts","is_correct":false},{"id":"d","text":"Bethesda","is_correct":true}],"explanation":"Microsoft adquirió ZeniMax Media, la matriz de Bethesda, en marzo de 2021."}]'::jsonb,
