insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-gta-trivia',
  'GTA Trivia: How Well Do You Know Grand Theft Auto?',
  'Eight questions on Grand Theft Auto: from the 1997 original to GTA V''s three protagonists and record-breaking launch.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'gaming'),
  '[{"id":"q1","question":"In which year was the first Grand Theft Auto released?","options":[{"id":"a","text":"1995","is_correct":false},{"id":"b","text":"1997","is_correct":true},{"id":"c","text":"1999","is_correct":false},{"id":"d","text":"2001","is_correct":false}],"explanation":"The original GTA, a top-down open-city game, came out in 1997."},{"id":"q2","question":"Liberty City, the setting of GTA III, is inspired by which real city?","options":[{"id":"a","text":"Chicago","is_correct":false},{"id":"b","text":"New York City","is_correct":true},{"id":"c","text":"Los Angeles","is_correct":false},{"id":"d","text":"Miami","is_correct":false}],"explanation":"Liberty City is the series'' stand-in for New York City."},{"id":"q3","question":"Which real city inspired GTA: Vice City?","options":[{"id":"a","text":"Miami","is_correct":true},{"id":"b","text":"Los Angeles","is_correct":false},{"id":"c","text":"Las Vegas","is_correct":false},{"id":"d","text":"New Orleans","is_correct":false}],"explanation":"Vice City (2002) recreates 1980s Miami, from neon boulevards to speedboats."},{"id":"q4","question":"Who is the protagonist of GTA: San Andreas?","options":[{"id":"a","text":"Tommy Vercetti","is_correct":false},{"id":"b","text":"Carl \"CJ\" Johnson","is_correct":true},{"id":"c","text":"Niko Bellic","is_correct":false},{"id":"d","text":"Claude","is_correct":false}],"explanation":"CJ returns to Los Santos after his mother''s murder in the 2004 game."},{"id":"q5","question":"In which year was Grand Theft Auto V released?","options":[{"id":"a","text":"2011","is_correct":false},{"id":"b","text":"2013","is_correct":true},{"id":"c","text":"2015","is_correct":false},{"id":"d","text":"2017","is_correct":false}],"explanation":"GTA V launched in September 2013 on PlayStation 3 and Xbox 360."},{"id":"q6","question":"How many playable protagonists does GTA V have?","options":[{"id":"a","text":"One","is_correct":false},{"id":"b","text":"Two","is_correct":false},{"id":"c","text":"Three","is_correct":true},{"id":"d","text":"Four","is_correct":false}],"explanation":"Michael, Franklin and Trevor can be swapped between missions."},{"id":"q7","question":"How quickly did GTA V reach one billion dollars in sales?","options":[{"id":"a","text":"In one day","is_correct":false},{"id":"b","text":"In three days","is_correct":true},{"id":"c","text":"In one week","is_correct":false},{"id":"d","text":"In one month","is_correct":false}],"explanation":"It made $800 million on day one and $1 billion in three days, then a record for an entertainment product."},{"id":"q8","question":"Which actor voiced Tommy Vercetti in GTA: Vice City?","options":[{"id":"a","text":"Samuel L. Jackson","is_correct":false},{"id":"b","text":"Michael Madsen","is_correct":false},{"id":"c","text":"Frank Vincent","is_correct":false},{"id":"d","text":"Ray Liotta","is_correct":true}],"explanation":"Liotta, already famous for Goodfellas, gave the 1980s mobster his voice."}]'::jsonb,
  null,
  array['gaming', 'gta', 'trivia', 'grand theft auto', 'rockstar']::text[],
  3,
  'published',
