insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-call-of-duty-trivia',
  'Call of Duty Trivia: How Well Do You Know the Saga?',
  'Eight questions on Call of Duty: World War II origins, Modern Warfare, Black Ops, Zombies and Warzone.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'gaming'),
  '[{"id":"q1","question":"In which year was the first Call of Duty released?","options":[{"id":"a","text":"2001","is_correct":false},{"id":"b","text":"2003","is_correct":true},{"id":"c","text":"2005","is_correct":false},{"id":"d","text":"2007","is_correct":false}],"explanation":"The original Call of Duty launched for PC in October 2003."},{"id":"q2","question":"Which studio developed the original Call of Duty?","options":[{"id":"a","text":"Treyarch","is_correct":false},{"id":"b","text":"Infinity Ward","is_correct":true},{"id":"c","text":"Sledgehammer Games","is_correct":false},{"id":"d","text":"EA DICE","is_correct":false}],"explanation":"Infinity Ward was founded to make the 2003 game and later created Modern Warfare."},{"id":"q3","question":"In which conflict were the first Call of Duty games set?","options":[{"id":"a","text":"World War I","is_correct":false},{"id":"b","text":"World War II","is_correct":true},{"id":"c","text":"Vietnam War","is_correct":false},{"id":"d","text":"Gulf War","is_correct":false}],"explanation":"The series began in World War II with American, British and Soviet campaigns."},{"id":"q4","question":"Which 2007 game first took the series into a modern-day setting?","options":[{"id":"a","text":"Call of Duty 3","is_correct":false},{"id":"b","text":"Call of Duty: World at War","is_correct":false},{"id":"c","text":"Call of Duty 4: Modern Warfare","is_correct":true},{"id":"d","text":"Call of Duty: Ghosts","is_correct":false}],"explanation":"Modern Warfare traded WWII for a fictional present-day conflict and reset the series."},{"id":"q5","question":"Which studio created the Black Ops sub-series?","options":[{"id":"a","text":"Infinity Ward","is_correct":false},{"id":"b","text":"Sledgehammer Games","is_correct":false},{"id":"c","text":"Raven Software","is_correct":false},{"id":"d","text":"Treyarch","is_correct":true}],"explanation":"Treyarch launched the Black Ops line in 2010 after World at War."},{"id":"q6","question":"Zombies mode debuted as a 