   is_featured, is_ai_generated, published_at)
values (
  'en-arcade-classics-trivia',
  'Arcade Classics Trivia: Pac-Man, Space Invaders and More',
  'Eight questions on arcade classics: Space Invaders, Pac-Man, Donkey Kong and the cabinets that ruled the eighties.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'gaming'),
  '[{"id":"q1","question":"In which year did Taito release Space Invaders?","options":[{"id":"a","text":"1976","is_correct":false},{"id":"b","text":"1978","is_correct":true},{"id":"c","text":"1980","is_correct":false},{"id":"d","text":"1982","is_correct":false}],"explanation":"Space Invaders arrived in 1978 and kicked off the golden age of arcades."},{"id":"q2","question":"In which year was Pac-Man first released in Japan?","options":[{"id":"a","text":"1978","is_correct":false},{"id":"b","text":"1980","is_correct":true},{"id":"c","text":"1982","is_correct":false},{"id":"d","text":"1984","is_correct":false}],"explanation":"Pac-Man debuted in Japan in May 1980 and reached the US later that year."},{"id":"q3","question":"Which Namco designer created Pac-Man?","options":[{"id":"a","text":"Toru Iwatani","is_correct":true},{"id":"b","text":"Shigeru Miyamoto","is_correct":false},{"id":"c","text":"Tomohiro Nishikado","is_correct":false},{"id":"d","text":"Nolan Bushnell","is_correct":false}],"explanation":"Iwatani designed it at Namco; Nishikado made Space Invaders and Miyamoto Donkey Kong."},{"id":"q4","question":"In 1981''s Donkey Kong, Mario debuted under what name?","options":[{"id":"a","text":"Mr. Video","is_correct":false},{"id":"b","text":"Jumpman","is_correct":true},{"id":"c","text":"Mr. Carpenter","is_correct":false},{"id":"d","text":"Luigi","is_correct":false}],"explanation":"The hero was called Jumpman before being renamed Mario for the US release."},{"id":"q5","question":"Which 1981 arcade game has you guiding a frog across a road and a river?","options":[{"id":"a","text":"Q*bert","is_correct":false},{"id":"b","text":"Dig Dug","is_correct":false},{"id":"c","text":"Frogger","is_correct":true},{"id":"d","text":"Centipede","is_correct":false}],"explanation":"Frogger, made by Konami, dodges traffic on land and logs on the water."},{"id":"q6","question":"Which 1979 Atari game has you blasting drifting space rocks?","options":[{"id":"a","text":"Asteroids","is_correct":true},{"id":"b","text":"Galaga","is_correct":false},{"id":"c","text":"Defender","is_correct":false},{"id":"d","text":"Missile Command","is_correct":false}],"explanation":"Asteroids used vector graphics and became one of Atari''s biggest hits."},{"id":"q7","question":"Which 1991 Capcom game turned one-on-one fighting into an arcade phenomenon?","options":[{"id":"a","text":"Mortal Kombat","is_correct":false},{"id":"b","text":"Fatal Fury","is_correct":false},{"id":"c","text":"Killer Instinct","is_correct":false},{"id":"d","text":"Street Fighter II","is_correct":true}],"explanation":"Street Fighter II: The World Warrior popularized the versus-fighting genre in 1991."},{"id":"q8","question":"Violence in which 1992 arcade fighter helped spur the creation of the ESRB rating system?","options":[{"id":"a","text":"Street Fighter II","is_correct":false},{"id":"b","text":"Mortal Kombat","is_correct":true},{"id":"c","text":"Killer Instinct","is_correct":false},{"id":"d","text":"Final Fight","is_correct":false}],"explanation":"Digitized blood and Fatalities fed the hearings that led to the ESRB in 1994."}]'::jsonb,
  null,
  array['gaming', 'arcade', 'trivia', 'retro', 'pac-man']::text[],
  3,
  'published',
